/**
 * Les vignettes du SUIVI — le dossier et l'assistant, ce qui se fait après le
 * rendez-vous. Sorties de `VignettesConsultation.tsx` le 2026-09-25 quand
 * celui-ci passait 450 lignes (règle 22) ; elles restent sur l'orbite de la
 * consultation.
 *
 * Chacune reçoit l'index de la fiche active et montre l'état qui lui répond,
 * dans l'ordre des fiches de `systeme.contenu.ts`. Kit et doctrine :
 * `kit.tsx`. Les noms et les dates sont ceux d'une affaire d'exemple.
 */
import { styled } from "styled-components";

import { withOpacity } from "@/shared/design-tokens/color";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { px } from "@/shared/design-tokens/scale";
import { radius } from "@/shared/design-tokens/spacing";

import { BarreDEcran, Coche, Ligne, Point, Rangee, Texte, Tuile, Vignette } from "./kit";

/* ─────────────────────────────── Styles ─────────────────────────────── */

const Colonnes = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: ${px(8)};
`;

const Colonne = styled.div`
  display: flex;
  flex-direction: column;
  gap: ${px(6)};
  padding: ${px(8)};
  border-radius: ${radius.md};
  background: ${nuit.verreBas};
`;

const Frise = styled.ol`
  position: relative;
  display: flex;
  flex-direction: column;
  gap: ${px(12)};
  margin: 0;
  padding: 0 0 0 ${px(18)};
  list-style: none;

  &::before {
    content: "";
    position: absolute;
    left: ${px(4)};
    top: ${px(6)};
    bottom: ${px(6)};
    width: var(--border-thin);
    background: linear-gradient(180deg, ${nuit.marque}, ${nuit.accent});
  }
`;

const Recherche = styled.div`
  display: flex;
  align-items: center;
  gap: ${px(10)};
  padding: ${px(10)} ${px(12)};
  border-radius: ${radius.md};
  border: var(--border-thin) solid ${withOpacity(nuit.accent, 0.45)};
  background: ${nuit.voileLeger};
`;

/* ────────────────────────────── Vignettes ───────────────────────────── */

export function VignetteDossiers({ etat }: { etat: number }) {
  return (
    <Vignette etat={etat}>
      {etat === 0 && (
        <>
          <BarreDEcran>
            <span>Dossiers</span>
            <Texte>par étape</Texte>
          </BarreDEcran>
          <Colonnes>
            {[
              { titre: "Qualification", cartes: [70] },
              { titre: "En cours", cartes: [85, 60] },
              { titre: "Terminés", cartes: [50] },
            ].map((colonne, i) => (
              <Colonne key={colonne.titre}>
                <Texte $fort>{colonne.titre}</Texte>
                {colonne.cartes.map((l, k) => (
                  <Tuile key={k} $vive={i === 1 && k === 0}>
                    <Ligne $largeur={l} />
                  </Tuile>
                ))}
              </Colonne>
            ))}
          </Colonnes>
        </>
      )}
      {etat === 1 && (
        <>
          <BarreDEcran>
            <span>Dossier Laurent</span>
            <Texte $accent>échéances</Texte>
          </BarreDEcran>
          <Frise>
            <li>
              <Texte>3 oct. · Mise en demeure envoyée</Texte>
            </li>
            <li>
              <Texte $fort $accent>
                12 nov. · Délai de réponse
              </Texte>
            </li>
            <li>
              <Texte>28 nov. · Conclusions à déposer</Texte>
            </li>
          </Frise>
        </>
      )}
      {etat >= 2 && (
        <>
          <BarreDEcran>
            <span>Espace client</span>
            <Texte $accent>partagé</Texte>
          </BarreDEcran>
          {["Bail signé.pdf", "Mise en demeure.pdf", "Compte rendu du 3 oct."].map((nom, i) => (
            <Tuile key={nom} $vive={i === 2}>
              <Rangee $entre>
                <Texte $fort={i === 2}>{nom}</Texte>
                <Point $ton={i === 2 ? "vif" : "ok"} />
              </Rangee>
            </Tuile>
          ))}
        </>
      )}
    </Vignette>
  );
}

export function VignetteAssistant({ etat }: { etat: number }) {
  return (
    <Vignette etat={etat}>
      {etat === 0 && (
        <>
          <BarreDEcran>
            <span>Rédaction</span>
            <Texte $accent>avec vous</Texte>
          </BarreDEcran>
          <Tuile>
            <Texte $fort>Réponse à la mise en demeure</Texte>
            <Ligne $largeur={95} />
            <Ligne $largeur={88} />
            <Ligne $largeur={70} $vive />
          </Tuile>
          <Rangee $ecart={8}>
            <Point $ton="ok" />
            <Texte>À partir des modèles du cabinet</Texte>
          </Rangee>
        </>
      )}
      {etat === 1 && (
        <>
          <BarreDEcran>
            <span>Veille</span>
            <Texte $accent>vos domaines</Texte>
          </BarreDEcran>
          {[70, 85, 60].map((l, i) => (
            <Tuile key={i} $vive={i === 0}>
              <Rangee $entre>
                <Texte $fort={i === 0}>{i === 0 ? "Nouvelle décision" : "Décision"}</Texte>
                {i === 0 ? <Point $ton="vif" /> : <Coche />}
              </Rangee>
              <Ligne $largeur={l} />
            </Tuile>
          ))}
        </>
      )}
      {etat >= 2 && (
        <>
          <Recherche>
            <Point $ton="vif" />
            <Texte $fort>clause de non-concurrence</Texte>
          </Recherche>
          {[90, 75, 82].map((l, i) => (
            <Tuile key={i}>
              <Ligne $largeur={l} $vive={i === 0} />
              <Ligne $largeur={l - 30} />
            </Tuile>
          ))}
        </>
      )}
    </Vignette>
  );
}
