import { useEffect, useState } from "react";

import type { IdServiceDeLaMarque } from "@/shared/config/services-de-la-marque";

import {
  BoutonDeFiche,
  Corps,
  LibelleDeFiche,
  ListeDesFiches,
  Progression,
  TexteDeFiche,
} from "./plongee.styles";
import { CONTENU_DES_SERVICES } from "./systeme.contenu";
import { VignetteDuService } from "./vignettes/VignetteDuService";

/**
 * Un service en détail — sa vignette codée et ses fiches. Le cœur de la
 * plongée, et ce que la frise déplie au téléphone : les deux formes montrent la
 * même chose, par le même composant.
 *
 * La fiche active pilote la vignette. Elle avance seule, avec sa barre, et
 * s'arrête tant qu'on la survole ou que le focus est dedans ; jamais au
 * mouvement réduit.
 */

/** Le temps d'une fiche : ~40 mots, lus sans hâte. */
const DUREE_FICHE_MS = 9_000;

export default function ServiceEnDetail({
  serviceId,
  mouvementReduit,
  empile = false,
}: {
  serviceId: IdServiceDeLaMarque;
  mouvementReduit: boolean;
  /** Au téléphone, la vignette passe au-dessus des fiches. */
  empile?: boolean;
}) {
  const contenu = CONTENU_DES_SERVICES[serviceId];
  const [fiche, setFiche] = useState(0);
  const [retenue, setRetenue] = useState(false);

  useEffect(() => {
    setFiche(0);
  }, [serviceId]);

  useEffect(() => {
    if (mouvementReduit || retenue || contenu.fiches.length < 2) return;
    const minuterie = window.setTimeout(
      () => setFiche((f) => (f + 1) % contenu.fiches.length),
      DUREE_FICHE_MS,
    );
    return () => window.clearTimeout(minuterie);
  }, [fiche, retenue, mouvementReduit, contenu.fiches.length]);

  return (
    <Corps
      $empile={empile}
      onMouseEnter={() => setRetenue(true)}
      onMouseLeave={() => setRetenue(false)}
      onFocus={() => setRetenue(true)}
      onBlur={(evenement) => {
        if (!evenement.currentTarget.contains(evenement.relatedTarget as Node | null)) setRetenue(false);
      }}
    >
      <VignetteDuService id={serviceId} etat={fiche} />
      <ListeDesFiches>
        {contenu.fiches.map((f, i) => (
          <li key={f.id}>
            <BoutonDeFiche type="button" aria-pressed={i === fiche} onClick={() => setFiche(i)}>
              <LibelleDeFiche>{f.libelle}</LibelleDeFiche>
              {i === fiche && (
                <>
                  <TexteDeFiche>{f.desc}</TexteDeFiche>
                  {!mouvementReduit && contenu.fiches.length > 1 && (
                    <Progression
                      key={`${serviceId}-${fiche}`}
                      $duree={DUREE_FICHE_MS}
                      $arretee={retenue}
                      aria-hidden="true"
                    />
                  )}
                </>
              )}
            </BoutonDeFiche>
          </li>
        ))}
      </ListeDesFiches>
    </Corps>
  );
}
