/**
 * Les vignettes de L'ARGENT du cabinet — la trésorerie et la facturation,
 * sorties de `VignettesCabinet.tsx` le 2026-09-25 quand celui-ci passait
 * 500 lignes (règle 22).
 *
 * Chacune reçoit l'index de la fiche active et montre l'état qui lui répond,
 * dans l'ordre des fiches de `systeme.contenu.ts`. Kit et doctrine :
 * `kit.tsx`. Les montants sont ceux d'une affaire d'exemple, écrits à la
 * française (règle 48).
 */
import { styled } from "styled-components";

import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { px } from "@/shared/design-tokens/scale";

import { BarreDEcran, Coche, montant, Point, Rangee, Texte, Tuile, Vignette } from "./kit";

/* ─────────────────────────────── Styles ─────────────────────────────── */

const Courbe = styled.svg`
  width: 100%;
  height: ${px(96)};
  overflow: visible;
`;

const Montant = styled.span`
  font-size: ${px(26)};
  font-weight: 700;
  color: ${nuit.encre};
  font-variant-numeric: tabular-nums;
`;

/* ────────────────────────────── Vignettes ───────────────────────────── */

export function VignetteTresorerie({ etat }: { etat: number }) {
  return (
    <Vignette etat={etat}>
      {etat === 0 && (
        <>
          <BarreDEcran>
            <span>Septembre</span>
            <Texte $accent>solde de la période</Texte>
          </BarreDEcran>
          <Montant>{montant(8_420)}</Montant>
          <Courbe viewBox="0 0 300 96" aria-hidden="true">
            <defs>
              <linearGradient id="vignette-tresorerie" x1="0" x2="1" y1="0" y2="0">
                <stop offset="0" stopColor={nuit.marque} />
                <stop offset="1" stopColor={nuit.accent} />
              </linearGradient>
            </defs>
            <path
              d="M0 80 C40 72 60 60 90 64 S150 40 180 44 S240 20 300 14"
              fill="none"
              stroke="url(#vignette-tresorerie)"
              strokeWidth={3}
              strokeLinecap="round"
            />
          </Courbe>
          <Rangee $entre>
            <Texte>Reste dû</Texte>
            <Texte $fort>{montant(1_560)}</Texte>
          </Rangee>
        </>
      )}
      {etat === 1 && (
        <>
          <BarreDEcran>
            <span>Relevé importé</span>
            <Texte $accent>4 lignes</Texte>
          </BarreDEcran>
          {[
            { libelle: "Loyer du cabinet", poste: "Locaux", somme: 1_200 },
            { libelle: "Cotisation ordinale", poste: "Ordre", somme: 380 },
            { libelle: "Abonnement logiciel", poste: "Outils", somme: 49 },
          ].map((ligne, i) => (
            <Tuile key={ligne.libelle} $vive={i === 0}>
              <Rangee $entre>
                <Texte $fort>{ligne.libelle}</Texte>
                <Texte>{montant(-ligne.somme)}</Texte>
              </Rangee>
              <Texte $accent>{ligne.poste}</Texte>
            </Tuile>
          ))}
        </>
      )}
      {etat >= 2 && (
        <>
          <BarreDEcran>
            <span>CARPA</span>
            <Texte $accent>rapprochement</Texte>
          </BarreDEcran>
          {["Dépôt · affaire Laurent", "Règlement · affaire Durand", "Frais · affaire Petit"].map((libelle, i) => (
            <Tuile key={libelle} $vive={i === 2}>
              <Rangee $entre>
                <Texte $fort={i === 2}>{libelle}</Texte>
                {i < 2 ? <Coche /> : <Point $ton="vif" />}
              </Rangee>
            </Tuile>
          ))}
        </>
      )}
    </Vignette>
  );
}

export function VignetteFacturation({ etat }: { etat: number }) {
  return (
    <Vignette etat={etat}>
      {etat === 0 && (
        <>
          <BarreDEcran>
            <span>Lien de paiement</span>
            <Texte $accent>sécurisé</Texte>
          </BarreDEcran>
          <Tuile $vive>
            <Texte>Consultation du jeudi 14 h</Texte>
            <Montant>{montant(120)}</Montant>
            <Rangee $ecart={8}>
              <Coche />
              <Texte $fort>Réglé avant le rendez-vous</Texte>
            </Rangee>
          </Tuile>
        </>
      )}
      {etat === 1 && (
        <>
          <BarreDEcran>
            <span>Facture n° 2026-0142</span>
            <Texte $accent>finalisée</Texte>
          </BarreDEcran>
          <Tuile>
            <Rangee $entre>
              <Texte>Base hors taxes</Texte>
              <Texte $fort>{montant(100)}</Texte>
            </Rangee>
            <Rangee $entre>
              <Texte>TVA 20 %</Texte>
              <Texte $fort>{montant(20)}</Texte>
            </Rangee>
            <Rangee $entre>
              <Texte $fort>Total</Texte>
              <Texte $fort $accent>
                {montant(120)}
              </Texte>
            </Rangee>
          </Tuile>
          <Rangee $ecart={8}>
            <Point $ton="ok" />
            <Texte>Numérotation continue, lien de paiement joint</Texte>
          </Rangee>
        </>
      )}
      {etat >= 2 && (
        <>
          <BarreDEcran>
            <span>Exports</span>
            <Texte $accent>comptabilité</Texte>
          </BarreDEcran>
          {["Factures de septembre · CSV", "Écritures 2026 · FEC"].map((nom, i) => (
            <Tuile key={nom} $vive={i === 1}>
              <Rangee $entre>
                <Texte $fort>{nom}</Texte>
                <Coche />
              </Rangee>
            </Tuile>
          ))}
        </>
      )}
    </Vignette>
  );
}
