import type { ComponentType } from "react";

import type { IdServiceDeLaMarque } from "@/shared/config/services-de-la-marque";

import { VignetteFacturation, VignetteTresorerie } from "./VignettesArgent";
import {
  VignetteDrive,
  VignetteOutils,
  VignetteProfil,
  VignetteSignature,
  VignetteTiroir,
} from "./VignettesCabinet";
import { VignetteAgenda, VignetteTranscription, VignetteVisio } from "./VignettesConsultation";
import { VignetteAssistant, VignetteDossiers } from "./VignettesSuivi";

/**
 * La vignette de chaque service — une par carte de la couverture LinkedIn.
 * Le type exige les douze : un service ajouté à la source sans sa vignette ne
 * compile pas.
 */
const VIGNETTES: Record<IdServiceDeLaMarque, ComponentType<{ etat: number }>> = {
  visio: VignetteVisio,
  transcription: VignetteTranscription,
  agenda: VignetteAgenda,
  "profil-public": VignetteProfil,
  dossiers: VignetteDossiers,
  "assistant-ia": VignetteAssistant,
  tresorerie: VignetteTresorerie,
  facturation: VignetteFacturation,
  drive: VignetteDrive,
  signature: VignetteSignature,
  "outils-externes": VignetteOutils,
  "et-bien-plus": VignetteTiroir,
};

export function VignetteDuService({ id, etat }: { id: IdServiceDeLaMarque; etat: number }) {
  const Composant = VIGNETTES[id];
  return <Composant etat={etat} />;
}
